module fsm (
	input clk,
	input reset,
	input k,
	input l,
	output reg u);

	parameter D=0, E=1, S1=2, S2=3, S3=4, S4=5, S5=6;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= D;
		else state <= next;
	end

	always_comb begin
		case (state)
			D: next = k ? E : D;
			E: next = l ? S1 : S2;
			S1: next = l ? S2 : S3;
			S2: next = l ? S3 : S4;
			S3: next = l ? S4 : S5;
			S4: next = l ? S5 : D;
			S5: next = k ? E : D;
			default: next = 'x;
		endcase
	end

	assign u = (state == S1);

endmodule

