module top_module(s_out, s_in_a, s_in_b, shift_ctrl, clear_b, clk);output s_out;
    input s_in_a, s_in_b, shift_ctrl, clear_b, clk;
    reg [1:0] sum;

    always @(posedge clk, negedge clear_b) begin
        if (!clear_b)
            sum <= 2'b10;
        else if (shift_ctrl)
            sum <= s_in_a + !s_in_b + sum[1];
    end
    assign s_out = sum[0];endmodule

