Build a 4-bit register with synchronous active low reset signal and a shift left enable signal. When the shift left enable signal is high, the register shifts left by one bit.
// (1) reset_n: Resets the register to 4'b0000 when low.
// (2) shift_left_enable: Enables the shift left operation when high.
// (3) data_in: The data to be shifted into the register.
// (4) q: The current state of the register.

module shift_left_register(
    input clk,
    input reset_n,
    input shift_left_enable,
    input data_in,
    output reg [3:0] q);

code:
module shift_left_register(
    input clk,
    input reset_n,
    input shift_left_enable,
    input data_in,
    output reg [3:0] q
);

    always @(posedge clk) begin
        if (!reset_n) begin
            // Synchronous reset: Reset the register to 4'b0000
            q <= 4'b0000;
        end else if (shift_left_enable) begin
            // Shift left operation: Shift left by one bit and input data_in
            q <= {q[2:0], data_in};
        end
    end

endmodule

