module automatic_door (
        input clk,
        input areset,
        input open_signal,
        input close_signal,
        output reg door_open);parameter Closed=1'b0, Open=1'b1;
	reg state;
	always @(posedge clk or posedge areset) begin
		if (areset)
			state <= Closed;
		else begin
			case (state)
				Closed: state <= open_signal ? Open : Closed;
				Open: state <= close_signal ? Closed : Open;
			endcase
		end
	end

	assign door_open = (state == Open);

endmodule

