module shift_register(clk, rst, serial_in, parallel_out);

    input clk;
    input rst;
    input serial_in;
    output [15:0] parallel_out;
    reg [15:0] parallel_out;

    always @(posedge clk or posedge rst)
    begin
        if (rst)
            parallel_out <= 16'b0000000000000000;
        else
            parallel_out <= {parallel_out[14:0], serial_in};
    end

endmodule

