module top_module(
	input wire VGA_clk,
	output reg [9:0] CountxAxis, CountyAxis, 
	output reg displayArea,
    output VGA_hSync, VGA_vSync
    );reg p_hSync, p_vSync;

	integer porchHF = 640; 
	integer syncH = 656;
	integer porchHB = 752; 
	integer maxH = 800; 

	integer porchVF = 480; 
	integer syncV = 490; 
	integer porchVB = 492; 
	integer maxV = 525; 

	always@(posedge VGA_clk)
    begin
		if(CountxAxis == maxH)
			CountxAxis <= 0;
		else
			CountxAxis <= CountxAxis + 1'b1;
	end

	always@(posedge VGA_clk)
    begin
		if(CountxAxis == maxH)
    begin
			if(CountyAxis == maxV)
				CountyAxis <= 0;
			else
			CountyAxis <= CountyAxis + 1'b1;
		end
	end

	always@(posedge VGA_clk)
    begin
		displayArea <= ((CountxAxis < porchHF) && (CountyAxis < porchVF)); 
	end

