module top_module(
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the register
    input select,     // Select input to choose between register and counter
    output [7:0] q    // 8-bit output from the minimum value module
);reg [7:0] reg_out;
    reg [3:0] counter_out;
    wire [7:0] min_val;

    // Register module with active high synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            reg_out <= 8'h34;
        end else begin
            reg_out <= d;
        end
    end

    // Counter module with synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            counter_out <= 4'b0;
        end else if (select) begin
            counter_out <= counter_out + 1;
        end
    end

    // Minimum value module using priority encoder
    assign min_val = (reg_out < counter_out) ? reg_out : counter_out;
    assign q = {min_val, 8'b0};

endmodule

