module top_module(
    input clk,
    input rst_n,
    input exe2disp_data_wr,
    input [7:0] exe2disp_data_in,
    input exe2disp_valid_wr,
    input exe2disp_valid_in,
    input exe2disp_direction_req,
    input exe2disp_direction,
    input um2npe_data_wr,
    input [7:0] um2npe_data_in,
    input um2npe_valid_wr,
    input um2npe_valid_in,
    input disp2usermux_data_wr,
    input [7:0] disp2usermux_data_in,
    input disp2usermux_valid_wr,
    input disp2usermux_valid_in,
    output [7:0] exe2disp_data_out,
    output exe2disp_valid_out,
    output disp2exe_alf,
    output [7:0] um2npe_data_out,
    output um2npe_valid_out,
    output um2npe_alf,
    output [7:0] disp2usermux_data_out,
    output disp2usermux_valid_out,
    output usermux2disp_alf
);reg [7:0] pkt_buffer;
reg pkt_valid;
reg pkt_direction;

always @(posedge clk) begin
    if (!rst_n) begin
        pkt_buffer <= 8'h00;
        pkt_valid <= 1'b0;
        pkt_direction <= 1'b0;
    end else if (exe2disp_data_wr && exe2disp_direction_req) begin
        pkt_buffer <= exe2disp_data_in;
        pkt_valid <= exe2disp_valid_in;
        pkt_direction <= exe2disp_direction;
    end else if (um2npe_data_wr) begin
        pkt_buffer <= um2npe_data_in;
        pkt_valid <= um2npe_valid_in;
        pkt_direction <= 0;
    end else if (disp2usermux_data_wr) begin
        pkt_buffer <= disp2usermux_data_in;
        pkt_valid <= disp2usermux_valid_in;
        pkt_direction <= 1;
    end
end

assign exe2disp_data_out = pkt_buffer;
assign exe2disp_valid_out = pkt_valid && (pkt_direction == 0);
assign disp2exe_alf = pkt_valid && (pkt_direction == 0);
assign um2npe_data_out = pkt_buffer;
assign um2npe_valid_out = pkt_valid && (pkt_direction == 0);
assign um2npe_alf = pkt_valid && (pkt_direction == 0);
assign disp2usermux_data_out = pkt_buffer;
assign disp2usermux_valid_out = pkt_valid && (pkt_direction == 1);
assign usermux2disp_alf = pkt_valid && (pkt_direction == 1);

endmodule

