    assign D2 = (DIODE == FORWARD_BIAS) ? HIGH_LEVEL : LOW_LEVEL;
    assign D3 = (DIODE == FORWARD_BIAS) ? LOW_LEVEL : HIGH_LEVEL;
    assign D4 = (DIODE == FORWARD_BIAS) ? LOW_LEVEL : HIGH_LEVEL;

endmodule

