        r_c <= 0;
        rr_b <= 0;
        rr_e <= 0;
    end else begin
        r_c <= c;
        rr_b <= r_b;
        rr_e <= r_e;
    end
end

always @(posedge clk or posedge reset) begin
    if (reset) begin
        r_qx <= 0;
        rb <= 0;
    end else begin
        r_qx <= cx;
        e2 <= rr_e;
        rb <= rr_b; // rb can now be assigned properly
    end
end

assign q = e2 & c;

endmodule

