module top_module(
    input clk,
    input rst,
    output reg [1:0] count,
    output reg overflow
);always @(posedge clk or negedge rst) begin
        if(rst == 0) begin
            count <= 2'b00;
            overflow <= 0;
        end
        else begin
            if(count == 2'b11) begin
                count <= 2'b00;
                overflow <= 1;
            end
            else begin
                count <= count + 1;
                overflow <= 0;
            end
        end
    end

endmodule

module top_module(
     clk_d,
     rst,
     add_en,
     month_m1,
     co_year
    );input clk_d;
    input rst;
    input add_en;
    output reg [3:0] month_m1;
    output reg co_year;
    reg [3:0] month_m1_tmp;

    always@( posedge clk_d or posedge rst)
    if(rst)
        month_m1 <= 4'd0;
    else
        month_m1 <= month_m1_tmp;

    always@*
