module top_module(
    input clk,
    input reset, // Synchronous active-high reset
    input [5:0] data_in, // 6-to-1 multiplexer input
    input [2:0] sel, // 6-to-1 multiplexer select signal
    output reg [3:0] q // Final output from the functional module
);reg [3:0] mux_out; // Output from the 6-to-1 multiplexer
reg [3:0] reg_out; // Output from the dual-edge triggered flip-flop

// 6-to-1 multiplexer
always @(*) begin
    case (sel)
        3'b000: mux_out = data_in[3:0];
        3'b001: mux_out = data_in[7:4];
        3'b010: mux_out = data_in[11:8];
        3'b011: mux_out = data_in[15:12];
        3'b100: mux_out = data_in[19:16];
        3'b101: mux_out = data_in[23:20];
        default: mux_out = 4'b0;
    endcase
end

// Dual-edge triggered flip-flop
always @(posedge clk, negedge clk) begin
    if (reset) begin
        reg_out <= 4'b0;
    end else begin
        reg_out <= mux_out;
    end
end

// Functional module
always @(posedge clk, negedge clk) begin
    if (sel >= 3'b000 && sel <= 3'b101) begin
        q <= reg_out;
    end else begin
        q <= 4'b0;
    end
end

endmodule

module johnson_counter_5bit (
    input clk,
    input rst,
    output reg [4:0] q
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        q <= 5'b0;
    end else begin
        q <= {q[3:0], ~q[4]};
    end
end

endmodule

