module top_module(clk,reset,stall,IRQ,eret_M,NPC,PC);input clk;
	input reset;
	input stall;
	input IRQ;
	input eret_M;

	input [31:0] NPC;

	output reg [31:0] PC;


	parameter init_addr=32'h0000_3000,
			  exc_handler_addr=32'h0000_4180;



	always @(posedge clk)
		begin
			if(reset)PC<=init_addr;
			else if(eret_M)PC<=NPC;
			else if(IRQ)PC<=exc_handler_addr;
			else if(stall)PC<=PC;
			else PC<=NPC;
		end

endmodule

module fsm_module (
        input clk,
        input reset,
        input ctrl,
        output reg out);parameter Q0=0, Q1=1, Q2=2, Q3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= Q0;
		else state <= next;


	always_comb begin
		case (state)
			Q0: next = ctrl ? Q1 : Q0;
			Q1: next = ctrl ? Q2 : Q1;
			Q2: next = ctrl ? Q3 : Q2;
			Q3: next = ctrl ? Q0 : Q3;
			default: next = 'x;
		endcase
	end

	assign out = (state == Q0) || (state == Q2);

endmodule

