module debouncer(
	input clk,
	input noisy,
	output reg clean);reg [3:0] shift_reg;

always @(posedge clk)
	begin
		shift_reg <= {shift_reg[2:0], noisy};
		if (shift_reg == 4'b1111)
			clean <= 1'b1;
		else if (shift_reg == 4'b0000)
			clean <= 1'b0;
	end
endmodule

