description:
Design a clock divider that generates a square wave output signal (SCLKclk) at half the frequency of the input clock (clk). The circuit incorporates a reset feature that, when activated, initializes the output and internal state. On each rising edge of the input clock, the circuit toggles the output SCLKclk and increments an internal counter (cuenta_sclk), effectively controlling the timing of the output signal based on the input frequency.
module top_module(
       clk,
	   reset,
	   SCLKclk
       );

code:
module top_module(
       clk,
	   reset,
	   SCLKclk
       );input wire clk, reset;
	   output reg SCLKclk;


       reg cuenta_sclk;  
       always @(posedge clk)   
	   begin
	      if(reset) begin
		  cuenta_sclk<=1'd0;  
		  SCLKclk <=1'd0; 
		  end  else
		              begin	
		  if(cuenta_sclk == 1'd0)

				begin 
				cuenta_sclk<= 2'd00; 
				SCLKclk <= ~SCLKclk;
				end else
				cuenta_sclk <= cuenta_sclk + 1'b1;
		          end
	      end

endmodule

